export interface MdPost {
  id: string;
  title: string;
  content: string;
  date: string;
  time: string;
  likes: number;
  views: number;
  tags: string[];
}

function parseTags(value: string): string[] {
  return value
    .replace(/^\[|\]$/g, '')
    .split(',')
    .map((tag) => tag.trim().replace(/^["']|["']$/g, ''))
    .filter(Boolean);
}

function parsePost(path: string, raw: string): MdPost {
  const filename = path.split('/').pop()!.replace(/\.md$/i, '');
  let text = raw.replace(/^\uFEFF/, '');
  const meta: Record<string, string> = {};

  // 解析可选的 frontmatter（--- 包裹的头部信息）
  const fm = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/);
  if (fm) {
    fm[1].split(/\r?\n/).forEach((line) => {
      const idx = line.indexOf(':');
      if (idx > 0) {
        meta[line.slice(0, idx).trim()] = line.slice(idx + 1).trim();
      }
    });
    text = text.slice(fm[0].length);
  }

  // 去掉文件开头的空行和第一个一级标题
  const lines = text.split(/\r?\n/);
  while (lines.length > 0 && lines[0].trim() === '') lines.shift();
  let title = meta.title || '';
  if (lines[0]?.startsWith('# ')) {
    if (!title) title = lines[0].slice(2).trim();
    lines.shift();
  }

  return {
    id: filename,
    title: title || filename,
    content: lines.join('\n').trim(),
    date: meta.date || '',
    time: meta.time || '',
    likes: Number(meta.likes) || 0,
    views: Number(meta.views) || 0,
    tags: parseTags(meta.tags || ''),
  };
}

/** 读取 import.meta.glob 导入的 markdown，按日期倒序排列 */
export function parseMdPosts(modules: Record<string, string>): MdPost[] {
  return Object.entries(modules)
    .map(([path, raw]) => parsePost(path, raw))
    .sort((a, b) => (b.date || '').localeCompare(a.date || ''));
}
