import { Calendar, Clock, Heart, FileText, Lock } from "lucide-react";
import { useState, type FormEvent } from "react";
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { parseMdPosts, type MdPost } from '../lib/mdPosts';

const THOUGHTS_PASSWORD = "021006";
const UNLOCK_KEY = "thoughts-unlocked";

// 自动读取 碎碎念/ 目录下的所有 markdown 文件
const mdModules = import.meta.glob('/碎碎念/*.md', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>;

const posts: MdPost[] = parseMdPosts(mdModules);

export default function Thoughts() {
  const [selectedPost, setSelectedPost] = useState<string | null>(
    posts[0]?.id ?? null
  );
  const [unlocked, setUnlocked] = useState(
    () => sessionStorage.getItem(UNLOCK_KEY) === "1"
  );
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleUnlock = (e: FormEvent) => {
    e.preventDefault();
    if (password === THOUGHTS_PASSWORD) {
      sessionStorage.setItem(UNLOCK_KEY, "1");
      setUnlocked(true);
      setError("");
      setPassword("");
    } else {
      setError("密码错误，请重试");
    }
  };

  if (!unlocked) {
    return (
      <div className="max-w-7xl mx-auto px-6 py-12">
        <div className="max-w-md mx-auto bg-white rounded-2xl shadow-lg p-8 mt-12">
          <div className="flex flex-col items-center text-center mb-6">
            <div className="w-14 h-14 rounded-full bg-slate-100 flex items-center justify-center mb-4">
              <Lock className="w-6 h-6 text-slate-600" />
            </div>
            <h1 className="text-2xl font-bold text-slate-900 mb-2">碎碎念</h1>
            <p className="text-slate-500 text-sm">这里是一些私人的碎碎念，请输入密码后查看</p>
          </div>
          <form onSubmit={handleUnlock} className="space-y-4">
            <input
              type="password"
              value={password}
              onChange={(e) => {
                setPassword(e.target.value);
                setError("");
              }}
              placeholder="请输入密码"
              autoFocus
              className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-slate-900/20 focus:border-slate-400 text-slate-900"
            />
            {error && <p className="text-sm text-red-500">{error}</p>}
            <button
              type="submit"
              className="w-full py-3 rounded-xl bg-slate-900 text-white font-medium hover:bg-slate-800 transition-colors"
            >
              解锁
            </button>
          </form>
        </div>
      </div>
    );
  }

  const selectedPostData = posts.find(p => p.id === selectedPost);

  return (
    <div className="max-w-7xl mx-auto px-6 py-12">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-slate-900 mb-2">碎碎念</h1>
        <p className="text-slate-600">记录生活中的点点滴滴</p>
      </div>

      {posts.length === 0 ? (
        <div className="bg-white rounded-2xl shadow-lg p-12 flex flex-col items-center text-center">
          <div className="w-16 h-16 rounded-full bg-slate-100 flex items-center justify-center mb-4">
            <FileText className="w-7 h-7 text-slate-400" />
          </div>
          <p className="text-slate-500">还没有碎碎念，去 碎碎念/ 目录写一篇 markdown 吧</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-8">
            <div className="bg-white rounded-2xl shadow-lg p-8">
              {selectedPostData ? (
                <article className="prose prose-slate max-w-none">
                  <h2 className="text-2xl font-bold text-slate-900 mb-4">
                    {selectedPostData.title}
                  </h2>

                  {(selectedPostData.date || selectedPostData.time || selectedPostData.likes > 0) && (
                    <div className="flex items-center gap-4 text-sm text-slate-500 mb-6 pb-6 border-b border-slate-200">
                      {selectedPostData.date && (
                        <div className="flex items-center gap-1">
                          <Calendar className="w-4 h-4" />
                          <span>{selectedPostData.date}</span>
                        </div>
                      )}
                      {selectedPostData.time && (
                        <div className="flex items-center gap-1">
                          <Clock className="w-4 h-4" />
                          <span>{selectedPostData.time}</span>
                        </div>
                      )}
                      {selectedPostData.likes > 0 && (
                        <div className="flex items-center gap-1">
                          <Heart className="w-4 h-4 fill-red-500 text-red-500" />
                          <span>{selectedPostData.likes}</span>
                        </div>
                      )}
                    </div>
                  )}

                  <div className="text-slate-700 leading-relaxed">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{selectedPostData.content}</ReactMarkdown>
                  </div>
                </article>
              ) : (
                <div className="text-center text-slate-400 py-12">
                  请从右侧选择一篇文章
                </div>
              )}
            </div>
          </div>

          <div className="lg:col-span-4">
            <div className="bg-white rounded-2xl shadow-lg p-6 sticky top-24">
              <h3 className="text-lg font-semibold text-slate-900 mb-4">文章列表</h3>
              <div className="space-y-3">
                {posts.map((post) => (
                  <button
                    key={post.id}
                    onClick={() => setSelectedPost(post.id)}
                    className={`w-full text-left p-4 rounded-xl transition-all ${
                      selectedPost === post.id
                        ? "bg-slate-900 text-white shadow-md"
                        : "bg-slate-50 text-slate-700 hover:bg-slate-100"
                    }`}
                  >
                    <div className="font-medium mb-2 line-clamp-1">{post.title}</div>
                    <div className={`text-sm flex items-center gap-2 ${
                      selectedPost === post.id ? "text-slate-300" : "text-slate-500"
                    }`}>
                      <Calendar className="w-3 h-3" />
                      <span>{post.date || "未标注日期"}</span>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
