import { ExternalLink, FolderOpen } from "lucide-react";
import { generatedDemos, type PortfolioDemo } from "../data/demos.generated";

// 作品数据由 scripts/sync-demos.mjs 自动生成
// 标题/描述/标签在 demos.config.json 里修改
const demos: PortfolioDemo[] = generatedDemos;

function resolveLink(link?: string) {
  if (!link) return undefined;
  if (/^(https?:)?\/\//.test(link)) return link;
  return `${import.meta.env.BASE_URL}${link.replace(/^\//, '')}`;
}

export default function Portfolio() {
  return (
    <div className="max-w-7xl mx-auto px-6 py-12">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-slate-900 mb-2">作品集</h1>
        <p className="text-slate-600">一些自己动手写的小 demo 与练习作品</p>
      </div>

      {demos.length === 0 ? (
        <div className="bg-white rounded-2xl shadow-lg p-12 flex flex-col items-center text-center">
          <div className="w-16 h-16 rounded-full bg-slate-100 flex items-center justify-center mb-4">
            <FolderOpen className="w-7 h-7 text-slate-400" />
          </div>
          <p className="text-slate-500">作品还在整理中，敬请期待</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {demos.map((demo) => (
            <article
              key={demo.id}
              className="bg-white rounded-2xl shadow-lg p-6 flex flex-col hover:shadow-xl hover:-translate-y-1 transition-all duration-300"
            >
              <h2 className="text-lg font-semibold text-slate-900 mb-2">
                {demo.title}
              </h2>
              <p className="text-slate-600 text-sm leading-relaxed flex-1">
                {demo.description}
              </p>

              <div className="flex flex-wrap gap-2 mt-4">
                {demo.tags.map((tag) => (
                  <span
                    key={tag}
                    className="px-2.5 py-1 bg-slate-100 text-slate-600 rounded-full text-xs"
                  >
                    {tag}
                  </span>
                ))}
              </div>

              <div className="flex items-center justify-between mt-5 pt-4 border-t border-slate-100">
                <span className="text-xs text-slate-400">{demo.date}</span>
                <div className="flex items-center gap-4">
                  {demo.link && (
                    <a
                      href={resolveLink(demo.link)}
                      target="_blank"
                      rel="noreferrer"
                      className="flex items-center gap-1 text-sm text-slate-600 hover:text-slate-900"
                    >
                      <ExternalLink className="w-4 h-4" />
                      预览
                    </a>
                  )}
                </div>
              </div>
            </article>
          ))}
        </div>
      )}
    </div>
  );
}
